import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";

function PrintProcessPage() {
  const { t } = useTranslation();

  const steps = [
    {
      title: t("process.step1.title", "01. Regional Foraging"),
      text: t(
        "process.step1.text",
        "Wild specimens are ethically harvested across local forests. Each mushroom is selected at peak maturity for its structural geometry while leaving mycelial networks intact."
      ),
      images: [
        {
          src: `${process.env.PUBLIC_URL}/assets/gathering-fungi-1.jpg`,
          alt: "Gathering fungal specimens in the field",
        },
        {
          src: `${process.env.PUBLIC_URL}/assets/gathering-fungi-2.jpg`,
          alt: "Close-up of collected mushroom material for study",
        },
      ],
    },
    {
      title: t("process.step2.title", "02. Identification & Research"),
      text: t(
        "process.step2.text",
        "Before planning the print, each specimen is cross-referenced using the book \"Didžioji Lietuvos Grybų knyga\" to find out expected spore print colors."
      ),
      images: [
        {
          src: `${process.env.PUBLIC_URL}/assets/fungi-book1.jpg`,
          alt: "Reference book spread used for fungal identification",
        },
        {
          src: `${process.env.PUBLIC_URL}/assets/fungi-book2.jpg`,
          alt: "Open field guide pages with fungal species information",
        },
      ],
    },
    {
      title: t("process.step3.title", "03. Cap Preparation"),
      text: t(
        "process.step3.text",
        "Stems are trimmed to expose the spore-bearing lamellae (gills or pores), preparing the delicate structures for direct contact with the paper."
      ),
      images: [
        {
          src: `${process.env.PUBLIC_URL}/assets/preparing-for-print.jpg`,
          alt: "Preparing fungal material for spore print creation",
        },
      ],
    },
    {
      title: t("process.step4.title", "04. Spore Collection"),
      text: t(
        "process.step4.text",
        "Arranged on thick carton paper, the caps release millions of microscopic spores over several hours. Air currents create organic, unrepeatable variations in the final print."
      ),
      images: [
        {
          src: `${process.env.PUBLIC_URL}/assets/layout-on-carton2.jpg`,
          alt: "Spore signature being composed on a carton layout",
        },
      ],
    },
    {
      title: t("process.step5.title", "05. Macro Documentation"),
      text: t(
        "process.step5.text",
        "Using specialized macro lenses and controlled lighting, the finished deposits are photographed at high magnification to capture fine spore textures and radial geometry."
      ),
      images: [
        {
          src: `${process.env.PUBLIC_URL}/assets/spore-print-photography.jpg`,
          alt: "Macro photography of a spore print detail",
        },
      ],
    },
  ];

  return (
    <div className="container mx-auto px-4 py-10 md:py-14 text-white">
      <div className="mx-auto max-w-5xl">
        <div className="mb-10 text-center">
          <p className="text-sm font-semibold uppercase tracking-[0.35em] text-amber-400">
            {t("process.badge", "Studio process")}
          </p>
          <h1 className="mt-3 text-4xl font-bold md:text-5xl">
            {t("process.title", "Printing & photographing the spores")}
          </h1>
          <p className="mx-auto mt-4 max-w-4xl text-lg text-white/80">
            {t(
              "process.subtitle",
              "The process bridges direct biological art with high-magnification documentation. It balances physical evidence—the original organic spore deposit—with photographic interpretation, using macro techniques to isolate and enlarge the intricate geometry of each fungal pattern."
            )}
          </p>
        </div>

        <div className="grid gap-4 md:grid-cols-2 md:items-stretch">
          {steps.map((step) => (
            <article
              key={step.title}
              className="flex h-full min-h-[560px] flex-col gap-4 rounded-[24px] border border-white/10 bg-white/5 p-4 shadow-lg shadow-black/20 md:p-5"
            >
              <div className="overflow-hidden rounded-[18px] border border-white/10 bg-black/20">
                {step.images.length > 1 ? (
                  <div className="grid grid-cols-2 gap-2 p-2">
                    {step.images.map((image, index) => (
                      <img
                        key={`${step.title}-${index}`}
                        src={image.src}
                        alt={image.alt}
                        className="h-40 w-full rounded-[14px] border border-white/10 object-cover shadow-md shadow-black/20 md:h-52"
                      />
                    ))}
                  </div>
                ) : (
                  <img
                    src={step.images[0].src}
                    alt={step.images[0].alt}
                    className="h-56 w-full rounded-[14px] border border-white/10 object-cover p-2 shadow-md shadow-black/20 md:h-72"
                  />
                )}
              </div>

              <div className="px-1">
                <h2 className="text-2xl font-semibold text-amber-200 md:text-[1.55rem]">{step.title}</h2>
                <p className="mt-3 text-base leading-relaxed text-white/80">{step.text}</p>
              </div>
            </article>
          ))}
        </div>

        {/* ============================================================ */}
        {/* 3. MACRO ARCHIVE CURATORIAL CTA */}
        {/* ============================================================ */}
        <section className="mt-12 md:mt-16">
          <div className="mx-auto max-w-5xl rounded-[24px] border border-amber-400/20 bg-black/40 p-6 backdrop-blur-md shadow-2xl md:p-8">
            <div className="grid gap-6 md:grid-cols-[220px_minmax(0,1fr)] md:items-center">
              <img
                src={`${process.env.PUBLIC_URL}/assets/macro-archive-photo.png`}
                alt={t("processImages.macroArchivePhoto", "Macro Archive preview study")}
                className="mx-auto h-auto w-full max-w-[220px] rounded-[18px] border border-white/10 object-cover shadow-xl md:max-w-[260px]"
              />

              <div className="flex flex-col gap-5 md:gap-6">
                <div className="max-w-3xl">
                  <p className="text-sm font-semibold uppercase tracking-[0.32em] text-amber-400">
                    {t("home.macroArchive.kicker", "Curatorial Study")}
                  </p>
                  <h2 className="mt-2 text-3xl font-bold text-white md:text-4xl">
                    {t("home.macroArchive.title", "Macro Archive")}
                  </h2>
                  <p className="mt-3 text-base leading-relaxed text-white/80 md:text-lg">
                    {t(
                      "home.macroArchive.body",
                      "A focused high-magnification index of fungal surface studies, designed for exhibition review, institutional browsing, and close reading of material behavior across specimen sets."
                    )}
                  </p>
                </div>

                <Link
                  to="/macro-archive"
                  className="inline-flex w-fit items-center justify-center rounded-full border border-amber-400/40 bg-amber-600 px-6 py-3 text-sm font-semibold uppercase tracking-[0.24em] text-white transition-all hover:bg-amber-500"
                >
                  {t("home.macroArchive.button", "View Macro Archive")}
                </Link>
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}

export default PrintProcessPage;