import { Component } from "react";
import { withTranslation } from "react-i18next";

class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, errorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    const { t } = this.props;

    if (this.state.hasError) {
      return (
        <div className="flex min-h-screen items-center justify-center bg-[#0a0908] px-4 text-center text-white">
          <div className="max-w-md">
            <h1 className="text-4xl font-bold text-amber-400">
              {t("errorBoundary.title", "Something went wrong")}
            </h1>
            <p className="mt-4 text-white/80">
              {t(
                "errorBoundary.message",
                "An unexpected error occurred. Please refresh the page or return home."
              )}
            </p>
            <a
              href="/"
              className="mt-6 inline-block rounded-full border border-amber-400/40 bg-amber-600 px-6 py-3 text-sm font-semibold uppercase tracking-wider text-white transition hover:bg-amber-500"
            >
              {t("errorBoundary.button_home", "Go Home")}
            </a>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default withTranslation()(ErrorBoundary);
