import React, { useState } from "react";
import { Link } from "react-router-dom";
import GalleryFrame from "./GalleryFrame";
import PropTypes from "prop-types";
import { useTranslation } from "react-i18next";

function SporePrintCard({ item }) {
  const { t } = useTranslation();
  const [activeView, setActiveView] = useState("physical"); // 'macro' | 'physical'

  const localizedTitle = t(item.titleKey, item.title);
  const currentImage = activeView === "macro" ? item.macroImage : item.physicalPrintImage;
  const currentAlt = activeView === "macro"
    ? t("sporeCard.altMacro", { title: localizedTitle })
    : t("sporeCard.altPhysical", { title: localizedTitle });

  return (
    <article className="bg-black/40 backdrop-blur-md border border-white/10 rounded-xl p-6 flex h-full flex-col items-center shadow-2xl transition-all duration-300 hover:border-amber-500/30">
      <div className="flex space-x-2 mb-6 bg-white/5 p-1.5 rounded-lg border border-white/10 text-xs font-semibold uppercase tracking-wider text-white">
        <button
          onClick={() => setActiveView("macro")}
          aria-pressed={activeView === "macro"}
          className={`px-4 py-1.5 rounded-md transition-all ${activeView === "macro"
            ? "bg-amber-600 text-white shadow-md"
            : "text-white/70 hover:text-white hover:bg-white/10"
            }`}
        >
          {t("sporeCard.viewMacro", "Macro Detail")}
        </button>
        <button
          onClick={() => setActiveView("physical")}
          aria-pressed={activeView === "physical"}
          className={`px-4 py-1.5 rounded-md transition-all ${activeView === "physical"
            ? "bg-amber-600 text-white shadow-md"
            : "text-white/70 hover:text-white hover:bg-white/10"
            }`}
        >
          {t("sporeCard.viewPhysical", "Physical Print")}
        </button>
      </div>

      <Link to={`/prints/${item.id}`} className="w-full flex justify-center" aria-label={t("sporeCard.openDetails", { title: localizedTitle })}>
        <GalleryFrame
          src={currentImage}
          alt={currentAlt}
          frameColor={item.frameColor || "#231b15"}
          className="w-full flex justify-center"
          imageClassName="max-h-[380px] rounded-sm"
        />
      </Link>

      <div className="mt-6 flex w-full flex-1 flex-col justify-between text-center">
        <div>
          <h3 className="text-4xl font-bold text-white tracking-wide">
            {t(item.titleKey, item.title)}
          </h3>
          <div className="mt-4 pt-4 border-t border-white/10 flex flex-wrap justify-center gap-2 text-xs text-white/80">
            <span className="bg-white/10 px-3 py-1 rounded-full border border-white/10 text-white/90">
              <strong>{t("sporeCard.dimensions", "Dimensions")}:</strong> {item.dimensions}
            </span>
          </div>

          <p className="text-sm text-white/85 mt-3 max-w-md mx-auto line-clamp-2">
            {t(item.descriptionKey, "")}
          </p>
        </div>
      </div>
    </article>
  );
}

SporePrintCard.propTypes = {
  item: PropTypes.object.isRequired,
};

export default SporePrintCard;
