import { Link, useParams, Navigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useEffect, useState } from "react";
import { Helmet } from "react-helmet";
import GalleryFrame from "../components/GalleryFrame";
import sporePrintExhibition from "../data/sporePrintData";

function SporePrintPage() {
  const { t } = useTranslation();
  const { printId } = useParams();
  const [activeImage, setActiveImage] = useState(null);

  const print = sporePrintExhibition.find((item) => item.id === printId);

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [printId]);

  if (!print) {
    return <Navigate to="/" replace />;
  }

  const curatorNoteText = t(print.curatorNoteKey, print.curatorNote || "");
  const curatorParagraphs = curatorNoteText
    .split("\n\n")
    .map((paragraph) => paragraph.trim())
    .filter(Boolean);

  const pageTitle = `${t(print.titleKey, print.title)}${t("seo.printTitleSuffix")}`;
  const pageDescription = curatorNoteText
    .split("\n\n")[0]
    || t("seo.printDescription");

  return (
    <div className="container mx-auto px-4 py-10 md:py-14">
      <Helmet>
        <title>{pageTitle}</title>
        <meta name="description" content={pageDescription} />
      </Helmet>
      <div className="max-w-6xl mx-auto">
        <div className="mb-8">
          <Link
            to="/"
            className="inline-flex items-center rounded-full border border-amber-500/40 bg-white/5 px-4 py-2 text-sm font-semibold uppercase tracking-[0.25em] text-amber-200 transition hover:border-amber-400 hover:bg-amber-500/10"
          >
            ← {t("sporePrintPage.back")}
          </Link>
        </div>

        <div className="grid gap-10 lg:grid-cols-[1.1fr_0.9fr] items-start">
          <div className="flex justify-center lg:justify-start">
            <GalleryFrame
              src={print.physicalPrintImage}
              alt={t(print.titleKey, print.title)}
              frameColor={print.frameColor || "#231b15"}
              imageClassName="max-h-[72vh]"
            />
          </div>

          <div className="text-white">
            <p className="mb-2 text-sm font-semibold uppercase tracking-[0.35em] text-amber-400">
              {t("sporePrintPage.featured")}
            </p>
            <h1 className="text-4xl font-bold md:text-5xl">{t(print.titleKey, print.title)}</h1>
            <div className="mt-4 rounded-2xl border border-amber-400/20 bg-amber-500/5 p-4 text-sm leading-relaxed text-white/85 md:text-base">
              {curatorParagraphs.map((paragraph, index) => (
                <p key={`${print.id}-note-${index}`} className={index > 0 ? "mt-2" : ""}>
                  {paragraph}
                </p>
              ))}
            </div>

            <div className="mt-6 grid gap-3 sm:grid-cols-2">
              <div className="rounded-xl border border-white/10 bg-white/5 p-4">
                <p className="text-xs uppercase tracking-[0.25em] text-white/50">{t("sporePrintPage.dimensions")}</p>
                <p className="mt-2 text-sm text-white/90">{print.dimensions}</p>
              </div>
              <div className="rounded-xl border border-white/10 bg-white/5 p-4">
                <p className="text-xs uppercase tracking-[0.25em] text-white/50">{t("sporePrintPage.medium")}</p>
                <p className="mt-2 text-sm text-white/90">{t(print.mediumKey, print.medium)}</p>
              </div>
            </div>
          </div>
        </div>

        <section className="mt-14 border-t border-white/10 pt-10">
          <div className="mb-6 text-center">
            <p className="text-xs uppercase tracking-[0.35em] text-amber-400">{t("sporePrintPage.macroStudy")}</p>
            <h2 className="mt-2 text-3xl font-bold text-white">{t("sporePrintPage.macroSurfaceDetails")}</h2>
          </div>

          <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3">
            {print.macroGallery
              .filter((image) => !(print.galleryExclude || []).includes(image))
              .map((image, index) => (
                <button
                  key={`${print.id}-${index}`}
                  type="button"
                  onClick={() => setActiveImage({ src: image, alt: t("sporePrintPage.macroDetail", { title: t(print.titleKey), number: index + 1 }) })}
                  className="rounded-2xl border border-white/10 bg-white/5 p-3 text-left transition hover:border-amber-400/50 hover:bg-white/10"
                >
                  <img
                    src={image}
                    alt={t("sporePrintPage.macroDetail", { title: t(print.titleKey), number: index + 1 })}
                    className="h-[280px] w-full rounded-xl object-cover"
                    loading="lazy"
                  />
                </button>
              ))}
          </div>
        </section>

        <section className="my-16 text-center">
          <p className="text-xs font-semibold uppercase tracking-[0.32em] text-amber-400">
            {t("sporePrintPage.inquiryHeading")}
          </p>
          <p className="mx-auto mt-3 max-w-2xl text-base italic leading-relaxed text-white/80">
            {t("sporePrintPage.inquiryCaption")}
          </p>
          <Link
            to="/#contact-section"
            className="mt-6 inline-flex items-center justify-center rounded-full border border-amber-200/60 bg-[#D49B35] px-7 py-3 text-sm font-bold uppercase tracking-[0.2em] text-[#121212] transition-all hover:bg-[#e0af4f] hover:shadow-lg hover:shadow-amber-500/20 focus:outline-none focus:ring-2 focus:ring-amber-400 focus:ring-offset-2 focus:ring-offset-[#0a0908]"
          >
            {t("sporePrintPage.inquire")}
          </Link>
        </section>

        {activeImage && (
          <div
            className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 p-4 backdrop-blur-md"
            onClick={() => setActiveImage(null)}
            role="dialog"
            aria-modal="true"
            aria-label={t("sporePrintPage.expandedMacro")}
          >
            <div
              className="relative max-w-5xl rounded-[24px] border border-white/10 bg-zinc-950 p-4 shadow-2xl md:p-6"
              onClick={(event) => event.stopPropagation()}
            >
              <button
                type="button"
                className="absolute right-3 top-3 rounded-full bg-zinc-800 p-2.5 text-white shadow-lg ring-1 ring-white/20 transition hover:bg-zinc-700 hover:ring-white/40 active:scale-95"
                onClick={() => setActiveImage(null)}
                aria-label={t("sporePrintPage.closeLightbox")}
              >
                <svg className="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>

              <img
                src={activeImage.src}
                alt={activeImage.alt}
                className="max-h-[75vh] w-full rounded-[18px] object-contain"
              />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default SporePrintPage;

