import React from "react";
import PropTypes from "prop-types";

/**
 * GalleryFrame component simulating a museum-quality framed artwork presentation.
 * Uses an outer wooden/metal moulding and an inner passe-partout (mat board).
 */
function GalleryFrame({
  src,
  alt,
  frameColor = "#231b15", // Dark walnut wood by default
  matColor = "#f4f2ec",   // Off-white textured mat board
  className = "",
  imageClassName = "",
}) {
  return (
    <div
      className={`block w-full max-w-[520px] rounded-[2px] p-3 transition-all duration-300 sm:p-4 ${className}`}
      style={{
        backgroundColor: frameColor,
        boxShadow:
          "0 20px 40px rgba(0, 0, 0, 0.6), inset 0 0 10px rgba(0, 0, 0, 0.8)",
      }}
    >
      {/* Passe-partout (Mat Board) */}
      <div
        className="flex w-full items-center justify-center overflow-hidden p-6 sm:p-8 md:p-8"
        style={{
          backgroundColor: matColor,
          boxShadow: "inset 2px 2px 5px rgba(0, 0, 0, 0.3)",
        }}
      >
        {/* Artwork Image */}
        <img
          src={src}
          alt={alt}
          className={`block h-auto w-auto max-w-full object-contain ${imageClassName}`}
          style={{
            boxShadow: "0 2px 8px rgba(0, 0, 0, 0.25)",
          }}
        />
      </div>
    </div>
  );
}

GalleryFrame.propTypes = {
  src: PropTypes.string.isRequired,
  alt: PropTypes.string.isRequired,
  frameColor: PropTypes.string,
  matColor: PropTypes.string,
  className: PropTypes.string,
  imageClassName: PropTypes.string,
};

export default GalleryFrame;
