import { useEffect } from "react";
import { useLocation } from "react-router-dom";

// It's a good practice to keep your tracking ID in a constant or environment variable.
const GA_TRACKING_ID = "G-Y1TX7WW3VL";

/**
 * This component handles Google Analytics page view tracking for a Single Page Application (SPA).
 * It listens for route changes using `useLocation` from react-router-dom and sends a `page_view`
 * event to Google Analytics whenever the user navigates to a new page.
 *
 * It should be placed inside your Router component (e.g., <HashRouter> or <BrowserRouter>).
 */
function Analytics() {
  const location = useLocation();

  useEffect(() => {
    // Check if the gtag function is available (it's loaded from the script in public/index.html)
    if (typeof window.gtag !== "function") {
      return;
    }

    // Send a page_view event to Google Analytics
    window.gtag("config", GA_TRACKING_ID, {
      page_path: location.pathname + location.search + location.hash,
    });
  }, [location]); // The effect re-runs every time the location changes.

  return null; // This component doesn't render anything to the DOM.
}

export default Analytics;